-- Generated from Pulsa24Jam H2HR dashboard export.
-- Re-run safe: refreshes the app catalog so active retail products are Pulsa24Jam H2HR only.
BEGIN;

ALTER TABLE public.produk_provider_map
  ADD COLUMN IF NOT EXISTS special_code TEXT;
ALTER TABLE public.produk_provider_map
  ADD COLUMN IF NOT EXISTS mode TEXT NOT NULL DEFAULT 'normal';
ALTER TABLE public.produk_provider_map
  ADD COLUMN IF NOT EXISTS minimal_nominal BIGINT NULL;
ALTER TABLE public.produk_provider_map
  ADD COLUMN IF NOT EXISTS maksimal_nominal BIGINT NULL;
ALTER TABLE public.produk_provider_map
  ADD COLUMN IF NOT EXISTS fee_rp BIGINT NOT NULL DEFAULT 0;

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'uq_produk_provider_map_produk_provider_kode'
      AND conrelid = 'public.produk_provider_map'::regclass
  ) THEN
    ALTER TABLE public.produk_provider_map
      ADD CONSTRAINT uq_produk_provider_map_produk_provider_kode
      UNIQUE (produk_id, provider, kode_provider);
  END IF;
END $$;

CREATE TEMP TABLE p24_h2hr_seed (
  category_name TEXT NOT NULL,
  brand_name TEXT NOT NULL,
  sku TEXT NOT NULL,
  product_name TEXT NOT NULL,
  group_name TEXT NOT NULL,
  price_type TEXT NOT NULL,
  price BIGINT NOT NULL,
  maximum_nominal BIGINT NULL
) ON COMMIT DROP;
































CREATE TEMP TABLE p24_h2hr_seed_unique AS
SELECT DISTINCT ON (sku)
  category_name, brand_name, sku, product_name, group_name, price_type, price, maximum_nominal
FROM p24_h2hr_seed
ORDER BY sku;


VALUES ('pulsa24jam', true, now(), now())
ON CONFLICT (nama) DO UPDATE SET aktif = true, diubah_pada = now();

UPDATE public.produk_app_pricing
SET aktif = false, updated_at = now(), diubah_pada = now()
WHERE aktif = true;

UPDATE public.produk_provider_map
SET aktif = false, diubah_pada = now()
WHERE aktif = true;

UPDATE public.produk
SET aktif = false, diubah_pada = now()
WHERE aktif = true
  AND sku NOT IN (SELECT sku FROM p24_h2hr_seed_unique);

SELECT DISTINCT ON (LOWER(TRIM(category_name))) category_name, true, now(), now()
FROM p24_h2hr_seed_unique
ORDER BY LOWER(TRIM(category_name)), category_name
ON CONFLICT (nama) DO UPDATE SET aktif = true, diubah_pada = now();

SELECT DISTINCT ON (LOWER(TRIM(brand_name))) brand_name, true, now(), now()
FROM p24_h2hr_seed_unique
ORDER BY LOWER(TRIM(brand_name)), brand_name
ON CONFLICT (nama) DO UPDATE SET aktif = true, diubah_pada = now();

SELECT DISTINCT k.id, 0, 0, 0, 0, true, now(), now()
FROM p24_h2hr_seed_unique seed
JOIN LATERAL (
  SELECT id FROM public.kategori
  WHERE LOWER(TRIM(nama)) = LOWER(TRIM(seed.category_name))
  ORDER BY id LIMIT 1
) k ON true
ON CONFLICT (kategori_id) DO UPDATE SET aktif = true, updated_at = now();

SELECT seed.sku, seed.product_name, seed.group_name, k.id, b.id, seed.price_type,
       CASE WHEN seed.price_type = 'FIXED' THEN seed.price ELSE NULL END,
       seed.maximum_nominal, '00:00', '23:59', true, now(), now()
FROM p24_h2hr_seed_unique seed
JOIN LATERAL (
  SELECT id FROM public.kategori
  WHERE LOWER(TRIM(nama)) = LOWER(TRIM(seed.category_name))
  ORDER BY id LIMIT 1
) k ON true
JOIN LATERAL (
  SELECT id FROM public.brand
  WHERE LOWER(TRIM(nama)) = LOWER(TRIM(seed.brand_name))
  ORDER BY id LIMIT 1
) b ON true
ON CONFLICT (sku) DO UPDATE SET
  nama = EXCLUDED.nama,
  group_name = EXCLUDED.group_name,
  kategori_id = EXCLUDED.kategori_id,
  brand_id = EXCLUDED.brand_id,
  tipe_harga = EXCLUDED.tipe_harga,
  nominal = EXCLUDED.nominal,
  maksimal_nominal = EXCLUDED.maksimal_nominal,
  jam_buka = EXCLUDED.jam_buka,
  jam_tutup = EXCLUDED.jam_tutup,
  aktif = true,
  diubah_pada = now();

SELECT p.id, 'pulsa24jam', seed.price, seed.price, seed.group_name, seed.category_name, seed.sku, seed.product_name, 'ACTIVE', seed.brand_name, true, now(), now(), now(), now(), now()
FROM p24_h2hr_seed_unique seed
JOIN public.produk p ON p.sku = seed.sku
ON CONFLICT (produk_id) DO UPDATE SET
  provider = 'pulsa24jam',
  harga = EXCLUDED.harga,
  harga_dasar = EXCLUDED.harga_dasar,
  yuscom_group = EXCLUDED.yuscom_group,
  yuscom_category = EXCLUDED.yuscom_category,
  yuscom_sku = EXCLUDED.yuscom_sku,
  yuscom_name = EXCLUDED.yuscom_name,
  yuscom_status = 'ACTIVE',
  yuscom_display_brand = EXCLUDED.yuscom_display_brand,
  aktif = true,
  fetched_at = now(),
  updated_at = now(),
  diubah_pada = now();

SELECT p.id, 'pulsa24jam', seed.sku, 'normal', true, 1,
       CASE WHEN seed.price_type = 'OPEN_AMOUNT' THEN 1 ELSE NULL END,
       seed.maximum_nominal, 0, now(), now()
FROM p24_h2hr_seed_unique seed
JOIN public.produk p ON p.sku = seed.sku
ON CONFLICT (produk_id, provider, kode_provider) DO UPDATE SET
  mode = 'normal',
  aktif = true,
  prioritas = 1,
  minimal_nominal = EXCLUDED.minimal_nominal,
  maksimal_nominal = EXCLUDED.maksimal_nominal,
  fee_rp = 0,
  diubah_pada = now();

COMMIT;
